const LanguageContext = React.createContext({ lang: "FR", setLang: () => {}, t: (k) => k });
function useLang() { return React.useContext(LanguageContext); }
function LanguageProvider({ children }) {
  const [lang, setLang] = useState("FR");
  const t = (key) => TRANSLATIONS[lang]?.[key] ?? TRANSLATIONS.FR[key] ?? key;
  return <LanguageContext.Provider value={{ lang, setLang, t }}>{children}</LanguageContext.Provider>;
}


/* ---------- Paiement Stripe ---------- */
// ⚠️ Ton price_1U0pJTGoTQNFhM1HQbQmVb86 est un prix en mode TEST (visible dans l'URL Stripe que tu m'as donnée).
// Il te faut donc ta clé PUBLIQUE DE TEST (elle commence par "pk_test_...", PAS "pk_live_...").
// La création de session de paiement se fait maintenant côté serveur (api/create-checkout-session.js),
// qui utilise STRIPE_SECRET_KEY (variable d'environnement Vercel). Plus besoin de clé publique ici.

async function goToCheckout(lineItems, orderId) {
  try {
    const base = window.location.href.split("?")[0];
    const res = await fetch("/api/create-checkout-session", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        lineItems,
        orderId,
        successUrl: `${base}?order=${orderId}&paid=1`,
        cancelUrl: `${base}?order=${orderId}&paid=0`,
      }),
    });
    const data = await res.json();
    if (!res.ok || !data.url) {
      throw new Error(data.error || "Réponse invalide du serveur de paiement.");
    }
    window.location.href = data.url;
  } catch (e) {
    console.error("Erreur Stripe Checkout :", e);
    alert("Paiement indisponible : " + (e?.message || "erreur inconnue") + "\n\nOuvre la console du navigateur (F12) pour plus de détails.");
  }
}

