// Calcule les totaux du panier : promo "3 achetés = 4e offert" (par référence/priceId).
function computeCartTotals(items) {
  const rawSubtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const groups = {};
  for (const i of items) {
    const key = i.priceId || i.name;
    if (!groups[key]) groups[key] = { qty: 0, price: i.price, freeQty: 0 };
    groups[key].qty += i.qty;
  }
  let bogoDiscount = 0;
  for (const key in groups) {
    const g = groups[key];
    g.freeQty = Math.floor(g.qty / 4);
    bogoDiscount += g.freeQty * g.price;
  }
  const total = Math.max(0, rawSubtotal - bogoDiscount);
  return { rawSubtotal, bogoDiscount, total, groups };
}

/* ---------- Stockage persistant (Supabase) ---------- */
// Remplace l'ancien window.storage (qui n'existe que dans l'environnement Claude Artifacts
// et ne fonctionnait pas une fois l'app déployée sur Vercel — c'est pour ça que rien
// ne se sauvegardait). Voir src/lib/supabase.js pour la config du client.
//
// - shared=true  → stocké dans Supabase (table kv_store), visible par tout le monde
//   (avis produits, popup BOGO déjà vu par la boutique...).
// - shared=false → stocké en localStorage, propre au navigateur de la personne.
// Les produits et les commandes ont leurs propres tables dédiées (voir plus bas)
// pour pouvoir les filtrer/trier proprement côté admin.

async function storageGet(key, shared = false) {
  if (!shared) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }
  try {
    const { data, error } = await supabase.from("kv_store").select("value").eq("key", key).maybeSingle();
    if (error || !data) return null;
    return data.value;
  } catch {
    return null;
  }
}
async function storageSet(key, value, shared = false) {
  if (!shared) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false;
    }
  }
  try {
    const { error } = await supabase.from("kv_store").upsert({ key, value });
    return !error;
  } catch {
    return false;
  }
}

function mapProductRow(row) {
  return {
    id: row.id,
    name: row.name,
    price: Number(row.price),
    cat: row.cat,
    frontImg: row.front_img,
    backImg: row.back_img,
    priceId: row.price_id,
    tag: row.tag,
    stock: row.stock,
    limited: row.limited,
  };
}

function useCustomProducts() {
  const [custom, setCustom] = useState([]);
  const [loading, setLoading] = useState(true);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let active = true;
    (async () => {
      const { data, error } = await supabase
        .from("products")
        .select("*")
        .order("created_at", { ascending: false });
      if (active) {
        if (error) console.error("Erreur chargement produits Supabase :", error);
        setCustom(data ? data.map(mapProductRow) : []);
        setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [reloadKey]);

  async function addProduct(product) {
    const row = {
      id: product.id,
      name: product.name,
      price: product.price,
      cat: product.cat,
      front_img: product.frontImg,
      back_img: product.backImg,
      price_id: product.priceId,
      tag: product.tag,
      stock: product.stock,
      limited: product.limited,
    };
    const { error } = await supabase.from("products").insert(row);
    if (error) {
      console.error("Erreur ajout produit Supabase :", error);
      throw error;
    }
    setCustom((list) => [product, ...list]);
  }

  return { custom, loading, addProduct, refresh: () => setReloadKey((k) => k + 1) };
}

