/* ---------- Photo t-shirt "tournable" au doigt (drag gauche/droite) ---------- */

function SwipeJersey({ frontSrc = FRONT_IMG, backSrc = BACK_IMG, className = "" }) {
  const [baseAngle, setBaseAngle] = useState(0); // 0 = recto face avant, 180 = verso face avant
  const [dragDelta, setDragDelta] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [loadedFront, setLoadedFront] = useState(false);
  const [loadedBack, setLoadedBack] = useState(false);
  const startX = React.useRef(0);
  const width = React.useRef(300);
  const containerRef = React.useRef(null);

  function onDown(clientX) {
    setDragging(true);
    startX.current = clientX;
    if (containerRef.current) width.current = containerRef.current.offsetWidth || 300;
  }
  function onMove(clientX) {
    if (!dragging) return;
    const dx = clientX - startX.current;
    // pleine largeur glissée = 180° de rotation
    setDragDelta((dx / width.current) * 180);
  }
  function onUp() {
    const total = baseAngle + dragDelta;
    const normalized = ((total % 360) + 360) % 360;
    const settled = normalized > 90 && normalized < 270 ? 180 : 0;
    setBaseAngle(settled);
    setDragDelta(0);
    setDragging(false);
  }

  const angle = baseAngle + dragDelta;
  const currentlyShowingBack = (((angle % 360) + 360) % 360) > 90 && (((angle % 360) + 360) % 360) < 270;

  return (
    <div
      ref={containerRef}
      className={`relative w-full rounded-2xl overflow-hidden bg-[#0D0D12] border border-[#232330] bracket select-none cursor-grab active:cursor-grabbing ${className}`}
      style={{ perspective: "1200px" }}
      onMouseDown={(e) => onDown(e.clientX)}
      onMouseMove={(e) => onMove(e.clientX)}
      onMouseUp={onUp}
      onMouseLeave={() => dragging && onUp()}
      onTouchStart={(e) => onDown(e.touches[0].clientX)}
      onTouchMove={(e) => onMove(e.touches[0].clientX)}
      onTouchEnd={onUp}
    >
      {!(loadedFront && loadedBack) && (
        <div className="absolute inset-0 z-20 animate-pulse bg-gradient-to-br from-[#14141B] via-[#1a1a24] to-[#14141B]" />
      )}
      <div className="absolute inset-0 grid-bg pointer-events-none z-10" />

      <div
        className="absolute inset-0"
        style={{
          transformStyle: "preserve-3d",
          transform: `rotateY(${angle}deg)`,
          transition: dragging ? "none" : "transform 0.35s cubic-bezier(.22,1,.36,1)",
        }}
      >
        <img
          src={frontSrc}
          alt="Maillot WZT recto"
          draggable={false}
          onLoad={() => setLoadedFront(true)}
          className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-300 ${loadedFront ? "opacity-100" : "opacity-0"}`}
          style={{ backfaceVisibility: "hidden", WebkitBackfaceVisibility: "hidden" }}
        />
        <img
          src={backSrc}
          alt="Maillot WZT verso"
          draggable={false}
          onLoad={() => setLoadedBack(true)}
          className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-300 ${loadedBack ? "opacity-100" : "opacity-0"}`}
          style={{ backfaceVisibility: "hidden", WebkitBackfaceVisibility: "hidden", transform: "rotateY(180deg)" }}
        />
      </div>

      <div className="absolute bottom-3 left-4 z-10 flex items-center gap-1.5 font-display text-[10px] tracking-[0.25em] txt-soft uppercase pointer-events-none">
        <RotateCcw size={11} /> {currentlyShowingBack ? "VERSO" : "RECTO"}
      </div>
    </div>
  );
}




