function useReviews(productId = "global") {
  const key = `reviews:${productId}`;
  const [reviews, setReviews] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      const stored = await storageGet(key, true);
      if (active) {
        setReviews(stored ?? SEED_REVIEWS);
        setLoading(false);
      }
    })();
    return () => { active = false; };
  }, [key]);

  async function addReview(review) {
    const next = [{ ...review, id: `r-${Date.now()}` }, ...(reviews ?? [])];
    setReviews(next);
    await storageSet(key, next, true);
  }

  const avg = reviews && reviews.length ? reviews.reduce((s, r) => s + r.rating, 0) / reviews.length : 5;
  return { reviews: reviews ?? [], avg, loading, addReview };
}

