/* ---------- Popup "3 achetés = 4e offert" ---------- */

function BogoPopup({ setPage }) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    let active = true;
    (async () => {
      const seen = await storageGet("popup:bogo:seen", false);
      if (active && !seen) {
        const t = setTimeout(() => setVisible(true), 1200);
        return () => clearTimeout(t);
      }
    })();
    return () => { active = false; };
  }, []);

  async function close() {
    setVisible(false);
    await storageSet("popup:bogo:seen", true, false);
  }

  if (!visible) return null;
  return (
    <div className="fixed inset-0 bg-black/80 z-[70] flex items-center justify-center p-5" onClick={close}>
      <div onClick={(e) => e.stopPropagation()} className="relative card-clip bg-[#0D0D12] border border-[#B26BFF] max-w-md w-full p-8 pt-12 glow-purple text-center">
        <button onClick={close} aria-label="Fermer"
          className="absolute top-3 right-3 w-9 h-9 rounded-full bg-[#1B1B22] hover:bg-[#26262f] border border-[#3a3a46] text-white flex items-center justify-center transition-colors">
          <X size={18} />
        </button>
        <p className="text-5xl mb-3">🎁</p>
        <h3 className="font-hero font-900 text-3xl text-white uppercase leading-tight mb-3">
          3 T-shirts achetés<br />= le 4ᵉ offert
        </h3>
        <p className="font-body text-sm txt-white mb-6">Automatique dans le panier, aucun code à entrer.</p>
        <div className="flex flex-col gap-3">
          <button
            onClick={() => { close(); setPage("shop"); }}
            className="btn-clip bg-[#7B2FF7] hover:bg-[#8f47ff] text-white font-display uppercase tracking-wide text-sm px-5 py-3">
            Voir la boutique
          </button>
          <button onClick={close} className="font-body text-xs txt-soft hover:text-white text-center underline underline-offset-2">
            Continuer sur le site
          </button>
        </div>
      </div>
    </div>
  );
}

