function ProductCard({ p, addToCart, setPage }) {
  const lowStock = p.stock != null && p.stock <= 5;
  const [size, setSize] = useState("M");
  const [added, setAdded] = useState(false);
  const { t, lang } = useLang();

  function handleAddToCart() {
    addToCart({
      id: `${p.id}-${Date.now()}`,
      name: p.name,
      price: p.price,
      qty: 1,
      cut: CUTS[0],
      size,
      priceId: p.priceId,
      customize: false,
      gamertag: "",
      realname: "",
      flag: null,
    });
    setAdded(true);
    setTimeout(() => setPage("cart"), 400);
  }
  const name = TRANSLATIONS[lang]?.[`p_${p.id}_name`] || p.name;
  const description = TRANSLATIONS[lang]?.[`p_${p.id}_desc`] || p.description;

  if (p.comingSoon) {
    return (
      <div className="relative text-left card-clip bg-[#0D0D12] border border-[#232330] overflow-hidden">
        <div className="relative p-4 pb-0">
          <div className="relative aspect-[511/746] rounded-2xl bg-[#050507] border border-[#232330] flex items-center justify-center">
            <span className="bg-[#0D0D12] border border-[#B26BFF] px-4 py-2 rounded-md font-display text-sm uppercase tracking-wide" style={{ color: "#FFFFFF" }}>
              {t("coming_soon")}
            </span>
          </div>
        </div>
        <div className="p-5">
          <p className="font-body text-xs uppercase tracking-wide" style={{ color: "#F2F2F6" }}>{p.cat}</p>
          <p className="font-body text-xs mt-2" style={{ color: "#F2F2F6" }}>{p.comingSoonLabel || t("coming_soon_default")}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="relative card-clip bg-[#0D0D12] border border-[#232330] overflow-hidden">
      <div className="relative p-4 pb-0">
        <SwipeJersey frontSrc={p.frontImg || FRONT_IMG} backSrc={p.backImg || BACK_IMG} className="aspect-[511/746]" />
      </div>
      {p.tag && (
        <span className="absolute top-7 left-7 bg-[#7B2FF7] text-white text-[10px] font-display tracking-wider uppercase px-2 py-1 rounded z-20">
          {p.tag}
        </span>
      )}
      {lowStock && (
        <span className="absolute top-7 right-7 flex items-center gap-1 bg-[#050507]/90 border border-red-500/60 text-red-400 text-[10px] font-display tracking-wider uppercase px-2 py-1 rounded z-20">
          <Flame size={11} /> {p.stock} {t("restants")}
        </span>
      )}
      <div className="p-5">
        <h3 className="font-display font-600 text-xl mt-1" style={{ color: "#FFFFFF" }}>{name}</h3>
        {description && <p className="font-body text-sm mt-2 leading-relaxed" style={{ color: "#F2F2F6" }}>{description}</p>}
        {p.limited && <p className="font-body text-xs mt-2" style={{ color: "#F2F2F6" }}>{t("limited_edition")} · {p.limited} ex.</p>}

        <div className="flex items-end justify-between mt-4">
          <p className="font-hero txt-cyan font-700 text-2xl">{p.price.toFixed(2)} €</p>
          <div className="flex flex-col items-end gap-1.5">
            <span className="font-display text-[10px] uppercase tracking-widest" style={{ color: "#F2F2F6" }}>{t("size_label")}</span>
            <div className="flex gap-1">
              {CARD_SIZES.map((s) => (
                <button
                  key={s}
                  onClick={() => setSize(s)}
                  className="font-display text-[11px] w-9 h-9 rounded-md border transition-colors"
                  style={
                    size === s
                      ? { background: "#7B2FF7", borderColor: "#7B2FF7", color: "#FFFFFF" }
                      : { borderColor: "#232330", color: "#F2F2F6" }
                  }
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        </div>

        <button
          onClick={handleAddToCart}
          disabled={!p.priceId}
          className="btn-clip w-full mt-4 bg-[#7B2FF7] hover:bg-[#8f47ff] disabled:opacity-40 disabled:cursor-not-allowed text-white font-display uppercase tracking-wide text-sm px-5 py-3.5"
        >
          {added ? <Check size={16} className="inline mr-1" /> : null}
          {t("buy_button")}
        </button>
      </div>
    </div>
  );
}

