function Shop({ addToCart, setPage }) {
  const [filter, setFilter] = useState("Tous");
  const { t } = useLang();
  const cats = [["Tous", t("filter_all")], ["T-shirt", t("filter_tshirt")]];
  const { custom } = useCustomProducts();
  const allProducts = [...PRODUCTS, ...custom];
  const list = allProducts.filter((p) => filter === "Tous" || p.cat === filter);

  return (
    <div className="max-w-7xl mx-auto px-5 py-14">
      <Eyebrow>{t("shop_eyebrow")}</Eyebrow>
      <h1 className="font-hero font-900 text-4xl text-white mb-8 uppercase">{t("shop_title")}</h1>

      <div className="flex flex-wrap gap-3 mb-10">
        {cats.map(([id, label]) => (
          <button key={id} onClick={() => setFilter(id)}
            className={`btn-clip font-display text-sm uppercase tracking-wide px-4 py-2 border transition-colors ${
              filter === id ? "bg-[#7B2FF7] border-[#7B2FF7] text-white" : "border-[#232330] txt-soft hover:text-white"
            }`}>
            {label}
          </button>
        ))}
      </div>

      {list.length === 0 ? (
        <p className="font-body text-sm txt-soft text-center py-16">{t("shop_empty")}</p>
      ) : (
        <div className="grid sm:grid-cols-2 md:grid-cols-3 gap-6">
          {list.map((p) => <ProductCard key={p.id} p={p} addToCart={addToCart} setPage={setPage} />)}
        </div>
      )}
    </div>
  );
}

