/* ---------- App root ---------- */

function AppInner() {
  const [page, setPage] = useState("home");
  const [cart, setCart] = useState([]);
  const [orderResult, setOrderResult] = useState(null);

  function addToCart(item) {
    setCart((c) => [...c, item]);
  }
  function removeItem(id) {
    setCart((c) => c.filter((i) => i.id !== id));
  }
  function go(p) {
    setPage(p);
    window.scrollTo?.(0, 0);
  }

  // Retour depuis Stripe (paiement réussi ou annulé) : on relit la commande en attente.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const orderId = params.get("order");
    const paid = params.get("paid");
    if (!orderId) return;
    (async () => {
      const { data: pending, error } = await supabase
        .from("orders")
        .select("*")
        .eq("id", orderId)
        .maybeSingle();
      if (error) console.error("Erreur lecture commande Supabase :", error);
      if (paid === "1") {
        if (pending) {
          const { error: updErr } = await supabase
            .from("orders")
            .update({ status: "paid", paid_at: new Date().toISOString() })
            .eq("id", orderId);
          if (updErr) console.error("Erreur validation commande Supabase :", updErr);
          setOrderResult({ status: "paid", orderNumber: pending.order_number });
        }
        setCart([]);
      } else if (paid === "0" && pending) {
        setCart(pending.items || []);
        setOrderResult({ status: "cancelled" });
      }
      setPage("cart");
      window.history.replaceState({}, "", window.location.pathname);
    })();
  }, []);

  // Crée la commande (infos de livraison incluses) puis envoie vers le paiement Stripe.
  // Le maillot n'est marqué "à expédier" que si le paiement Stripe est confirmé au retour (paid=1).
  async function startCheckout(email, shipping) {
    const orderId = `${Date.now()}-${Math.floor(Math.random() * 100000)}`;
    const orderNumber = Math.floor(10000 + Math.random() * 89999);
    const { rawSubtotal, bogoDiscount, total, groups } = computeCartTotals(cart);
    const order = {
      id: orderId,
      order_number: orderNumber,
      email: email.trim().toLowerCase(),
      shipping,
      items: cart.map((i) => ({ id: i.id, name: i.name, size: i.size, cut: i.cut, qty: i.qty, price: i.price, priceId: i.priceId, gamertag: i.gamertag, realname: i.realname, flag: i.flag, customize: i.customize })),
      raw_subtotal: rawSubtotal,
      bogo_discount: bogoDiscount,
      total,
      status: "pending",
    };
    const { error: insErr } = await supabase.from("orders").insert(order);
    if (insErr) {
      console.error("Erreur création commande Supabase :", insErr);
      alert("Impossible d'enregistrer la commande. Réessaie dans un instant.");
      return;
    }

    // Quantité facturée sur Stripe = quantité du panier moins les exemplaires offerts (3 achetés = 4e offert),
    // par référence (priceId).
    const paidQtyByPrice = {};
    for (const key in groups) {
      const g = groups[key];
      const paidQty = g.qty - g.freeQty;
      if (paidQty > 0) paidQtyByPrice[key] = (paidQtyByPrice[key] || 0) + paidQty;
    }
    const lineItems = Object.entries(paidQtyByPrice)
      .filter(([priceId]) => cart.some((i) => (i.priceId || i.name) === priceId && i.priceId))
      .map(([priceId, quantity]) => ({ price: priceId, quantity }));
    if (lineItems.length === 0) {
      alert("Aucun article de ce panier n'a d'ID de prix Stripe configuré — paiement impossible.");
      return;
    }
    await goToCheckout(lineItems, orderId);
  }

  const cartCount = cart.reduce((s, i) => s + i.qty, 0);

  const particles = useMemo(() => {
    const colors = ["#35F2E8", "#B26BFF", "#FF2D95", "#4A6BFF"];
    return Array.from({ length: 28 }).map((_, i) => ({
      id: i,
      left: Math.random() * 100,
      size: 2 + Math.random() * 3,
      duration: 12 + Math.random() * 14,
      delay: -Math.random() * 20,
      color: colors[i % colors.length],
    }));
  }, []);

  return (
    <div className="min-h-screen bg-root font-body">
      <style>{FONT_STYLE}</style>
      <div className="bg-mesh" />
      <div className="bg-particles">
        {particles.map((p) => (
          <span key={p.id} style={{
            left: `${p.left}%`, width: p.size, height: p.size, color: p.color,
            background: p.color, animationDuration: `${p.duration}s`, animationDelay: `${p.delay}s`,
          }} />
        ))}
      </div>
      <div className="bg-scanlines" />
      <div className="bg-noise" />
      <BogoPopup setPage={go} />
      <Header page={page} setPage={go} cartCount={cartCount} />
      {page === "home" && <Home setPage={go} />}
      {page === "shop" && <Shop addToCart={addToCart} setPage={go} />}
      {page === "cart" && <Cart items={cart} removeItem={removeItem} addToCart={addToCart} onCheckout={startCheckout} setPage={go} orderResult={orderResult} />}
      {page === "shipping" && <Shipping />}
      {page === "about" && <About />}
      {page === "contact" && <Contact />}
      {page === "admin" && <AdminPage goShop={() => go("shop")} />}
      <Footer setPage={go} />
      {page !== "admin" && <AdminButton onUnlock={() => go("admin")} />}
    </div>
  );
}

export default function App() {
  return (
    <LanguageProvider>
      <AppInner />
    </LanguageProvider>
  );
}
